void sub_0200EB80(BgConfig *bgConfig, u8 bgLayer, u16 bgBaseTile, u8 withTile, u8 messageBoxFrame, u32 heapID);

void sub_0200EB80(BgConfig *bgConfig, u8 bgLayer, u16 bgBaseTile, u8 withTile, u8 messageBoxFrame, u32 heapID) {
    void *tiles;
    NNSG2dCharacterData *chars;
    u8 *src;
    u32 i;
    u8 srcTop, srcBot;

    tiles = GfGfxLoader_GetCharData(NARC_INDEX_GRAPHIC__PL_WINFRAME,
        sub_0200E63C(messageBoxFrame),
        0,
        &chars,
        (HeapID)heapID);
    src = Heap_Alloc(heapID, (8 * (8 / 2)) * 18);
    memcpy(src, chars->pRawData, (8 * (8 / 2)) * 18);

    for (i = 0; i < (8 * (8 / 2)) * 18; i++) {
        srcTop = src[i] >> 4;
        srcBot = src[i] & 0xF;

        if (srcTop == 0) {
            srcTop = withTile;
        }

        if (srcBot == 0) {
            srcBot = withTile;
        }

        src[i] = (srcTop << 4) | srcBot;
    }

    BG_LoadCharTilesData(bgConfig, bgLayer, src, (8 * (8 / 2)) * 18, bgBaseTile);
    Heap_Free(tiles);
    Heap_Free(src);
}

enum SignpostType {
    SIGNPOST_TYPE_MAP = 0,
    SIGNPOST_TYPE_ARROW = 1,
    SIGNPOST_TYPE_LANDMARK = 2,
    SIGNPOST_TYPE_SCROLLING = 3,
};

void BG_LoadPlttData(u32 bgLayer, void *src, u16 size, u16 offset);

void *AllocAndReadWholeNarcMemberByIdPair(enum NarcID narcID, int memberIndex, enum HeapID heapID);

u32 GfGfxLoader_LoadCharData(enum NarcID narcID, u32 narcMemberIdx, BgConfig *bgConfig, u32 bgLayer, u32 offset, u32 size, BOOL compressed, u32 heapID);

void Heap_FreeExplicit(u32 heapID, void *ptr);

void sub_0200EC84(BgConfig *bgConfig, u8 bgLayer, u16 offset, u8 param3, u16 narcMemberIdx, u32 heapID);

void LoadMapSignpostFrameAndGraphic(BgConfig *bgConfig, u8 bgLayer, u16 baseTile, u8 palette, u8 signpostType, u16 signpostNARCMemberIdx, u32 heapID);

void LoadMapSignpostFrameAndGraphic(BgConfig *bgConfig, u8 bgLayer, u16 baseTile, u8 palette, u8 signpostType, u16 signpostNARCMemberIdx, u32 heapID) {
    GfGfxLoader_LoadCharData(NARC_INDEX_GRAPHIC__FIELD_BOARD,
        0,
        bgConfig,
        bgLayer,
        baseTile,
        (((6 + 1 + 2) * 2) + ((4 + 1 + 1) * 2)) * (8 * (8 / 2)),
        0,
        heapID);

    void *signpostNclr = (void *)(AllocAndReadWholeNarcMemberByIdPair(NARC_INDEX_GRAPHIC__FIELD_BOARD, 1, (HeapID)(heapID)));

    NNSG2dPaletteData *paletteData;
    NNS_G2dGetUnpackedPaletteData(signpostNclr, &paletteData);
    u16 *paletteBuf = paletteData->pRawData;

    BG_LoadPlttData(bgLayer,
        paletteBuf + (signpostType * (16)),
        ((16) * sizeof(u16)),
        palette * ((16) * sizeof(u16)));
    Heap_FreeExplicit(heapID, signpostNclr);

    if (signpostType == SIGNPOST_TYPE_MAP || signpostType == SIGNPOST_TYPE_ARROW) {
        sub_0200EC84(bgConfig,
            bgLayer,
            baseTile + (((6 + 1 + 2) * 2) + ((4 + 1 + 1) * 2)),
            signpostType,
            signpostNARCMemberIdx,
            heapID);
    }
}
